import { createSlice, PayloadAction } from '@reduxjs/toolkit';
import { AuthCookieStorage } from '../../../utils/auth-cookie-stor';
import { IUser } from '../../../models/user';
import { getMeThunk } from './thunks';

interface IUserSliceState extends IUser {
    token: string | null,
    loading: boolean,
}

const name = 'user';
const initialState: IUserSliceState = {
    token: null,
    loading: true,
};

const userSlice = createSlice({
    name,
    initialState,
    reducers: {
        saveToken(state, action: PayloadAction<{ token: string }>) {
            AuthCookieStorage.auth = action.payload
            return { ...state, ...action.payload };
        },
    },

    extraReducers(builder) {
        builder.addCase(getMeThunk.pending, (state, action) => {
            return { ...state, loading: true }
        });
        builder.addCase(getMeThunk.fulfilled, (state, action) => {
            return { ...state, ...action.payload, loading: false }
        });
    },
});


export default userSlice;

export const { saveToken } = userSlice.actions;