
import { instance } from ".";

export const tradesApi = {
    getAll(body: { page?: number, pageSize?: number }) {
        return instance.post('/trades/all', body)
            .then(res => res.data)
    },
    addTrade(body: { message: string }) {
        return instance.post('/trades/add', body)
            .then(res => res.data)
    },

};