import React from 'react'
import { Avatar, Box, Button, Container, CssBaseline, TextField, Typography } from '@mui/material'
import LockOutlinedIcon from '@mui/icons-material/LockOutlined';
import useLogin from '../../hooks/useLogin';
import { Controller } from 'react-hook-form';

export default function SigninPage() {
    const { createForm, error, isLoad, onSubmit } = useLogin()

    return (
        <Container component="main" maxWidth="xs">
            <CssBaseline />
            <Box
                sx={{
                    marginTop: 8,
                    display: 'flex',
                    flexDirection: 'column',
                    alignItems: 'center',
                }}
            ></Box>
            <Avatar sx={{ m: 1, bgcolor: 'secondary.main' }}>
                <LockOutlinedIcon />
            </Avatar>
            <Typography component="h1" variant="h5">
                Sign in
            </Typography>
            {error.length > 0 &&
                <Typography component="h4" variant="h5" color={'red'}>
                    {error}
                </Typography>
            }
            <Box component="form" onSubmit={onSubmit} noValidate sx={{ mt: 1 }}>
                {
                    <Controller control={createForm.control} name="login" render={({ field }) => <TextField
                        margin="normal"
                        required
                        fullWidth
                        id="login"
                        label="Login"
                        autoComplete="login"
                        autoFocus
                        {...field}
                    />} />
                }
                {
                    <Controller control={createForm.control} name="password" render={({ field }) => <TextField
                        margin="normal"
                        required
                        fullWidth
                        label="Password"
                        type="password"
                        id="password"
                        autoComplete="current-password"
                        {...field}
                    />} />
                }


                <Button
                    disabled={isLoad}
                    type="submit"
                    fullWidth
                    variant="contained"
                    sx={{ mt: 3, mb: 2 }}
                >
                    Sign In
                </Button>
            </Box>
        </Container >
    )
}
