import React from "react";
import {
    createBrowserRouter,
    RouterProvider,
} from "react-router-dom";
import SigninPage from "../../pages/signin";
import ProtectedRoutes from "./internal-components/protected-routes";
import UnprotectedRoutes from "./internal-components/unprotected-routes";
import RulesPage from "../../pages/rules";
import ReputationPage from "../../pages/reputation";
import QuestionsPage from "../../pages/questions";
import FaqPage from "../../pages/faq";
import MainPage from "../../pages/main";
import MainLayout from "../../layouts/main";


const router = createBrowserRouter([
    {
        element: <UnprotectedRoutes />,
        children: [
            {
                path: "/signin",
                element: <SigninPage />,
            },
        ]
    },


    {
        element: <MainLayout><ProtectedRoutes /></MainLayout>,
        children: [
            {
                path: '/',
                element: <MainPage />
            },
            {
                path: '/rules',
                element: <RulesPage />
            },
            {
                path: '/reputation',
                element: <ReputationPage />
            },
            {
                path: '/questions',
                element: <QuestionsPage />
            }, {
                path: '/faq',
                element: <FaqPage />
            }
        ]
    }
]);

export default function Router() {
    return (
        <RouterProvider router={router} />
    );
}


